    stdout: "pipe",
    stderr: "pipe",
  });

  let timeoutId: ReturnType<typeof setTimeout> | undefined;
  if (timeoutSeconds && timeoutSeconds > 0) {
    timeoutId = setTimeout(
      () => {
        proc.kill();
      },
      Math.round(timeoutSeconds * 1000),
